edits.new:
// Hierarchical binomial-beta model (rat tumor style)
//   y_i    ~ Binomial(n_i, theta_i)
//   theta_i ~ Beta(alpha, beta)
//   p(alpha, beta) proportional to (alpha + beta)^(-5/2)
data {
  int<lower=0> N;                       // number of groups
  array[N] int<lower=0> n;              // trials
  array[N] int<lower=0> y;              // successes
}
parameters {
  real<lower=0> alpha;
  real<lower=0> beta;
  vector<lower=0, upper=1>[N] theta;
}
model {
  // hyperprior: p(alpha, beta) propto (alpha + beta)^(-5/2)
  target += -2.5 * log(alpha + beta);
  // population distribution
  theta ~ beta(alpha, beta);
  // likelihood
  y ~ binomial(n, theta);
}

input.command:
mkdir -p /tmp/t && cat > /tmp/t/marg.stan <<'EOF'
data { int<lower=0> N; array[N] int<lower=0> n; array[N] int<lower=0> y; }
parameters { real u; real v; }
transformed parameters {
  real<lower=0> alpha = exp(u+v)/(1+exp(u));
  real<lower=0> beta = exp(v)/(1+exp(u));
}
model {
  target += -2.5*v + log(alpha) + log(beta) - v;
  y ~ beta_binomial(n, alpha, beta);
}
EOF
cat > /tmp/t/repar.stan <<'EOF'
data { int<lower=0> N; array[N] int<lower=0> n; array[N] int<lower=0> y; }
parameters { real u; real v; vector<lower=0,upper=1>[N] theta; }
transformed parameters {
  real<lower=0> alpha = exp(u+v)/(1+exp(u));
  real<lower=0> beta = exp(v)/(1+exp(u));
}
model {
  target += -2.5*v + log(alpha) + log(beta) - v;
  theta ~ beta(alpha, beta);
  y ~ binomial(n, theta);
}
EOF
cd /tmp/t && Rscript -e '
library(rstan); rstan_options(auto_write=TRUE); options(mc.cores=4)
d<-read.csv("/app/data.csv"); sd_<-list(N=nrow(d),n=as.integer(d$n),y=as.integer(d$y))
for(f in c("marg.stan","repar.stan")){
 m<-stan_model(f); fit<-sampling(m,data=sd_,chains=4,iter=20000,seed=1,refresh=0,control=list(adapt_delta=0.95))
 p<-extract(fit,pars=c("alpha","beta")); cat(f,"alpha",mean(p$alpha),"beta",mean(p$beta),"ndiv",sum(sapply(get_sampler_params(fit,inc_warmup=FALSE),function(x)sum(x[,"divergent__"]))),"\n")}' 2>&1 | grep -v "^Chain\|^$" | tail -20

edits.new:
// Hierarchical binomial / beta model
//   y_i     ~ Binomial(n_i, theta_i)
//   theta_i ~ Beta(alpha, beta)
//   p(alpha, beta) proportional to (alpha + beta)^(-5/2)
//
// The hyperparameters are sampled on the numerically well behaved scale
//   u = log(alpha / beta),  v = log(alpha + beta)
// and the Jacobian of the transformation is added to the log density, so the
// implied prior on (alpha, beta) is exactly (alpha + beta)^(-5/2).
data {
  int<lower=0> N;                       // number of groups
  array[N] int<lower=0> n;              // trials
  array[N] int<lower=0> y;              // successes
}
parameters {
  real u;                               // log(alpha / beta)
  real v;                               // log(alpha + beta)
  vector<lower=0, upper=1>[N] theta;    // group success probabilities
}
transformed parameters {
  real<lower=0> alpha = exp(u + v) / (1 + exp(u));
  real<lower=0> beta  = exp(v) / (1 + exp(u));
}
model {
  // hyperprior p(alpha, beta) propto (alpha + beta)^(-5/2)
  // plus Jacobian log|d(alpha,beta)/d(u,v)| = log(alpha) + log(beta) - v
  target += -2.5 * v + log(alpha) + log(beta) - v;

  // population distribution
  theta ~ beta(alpha, beta);

  // likelihood
  y ~ binomial(n, theta);
}
